// Fail-closed gate, then route. Two actions, because both are operator chores that need the
// service-account credential and neither belongs in a scheduled workflow.
//
//   seed    — put a row into the Inbox tab exactly as a human typing would. Also bootstraps the
//             header row, which a Sheets append does when the tab is empty.
//   approve — mark ONE lead in Leads as `approved`.
//
// WHY `approve` EXISTS. A catch-all domain accepts mail for any address, so no verifier can
// confirm a specific mailbox on it. Reoon returns is_deliverable:true, is_safe_to_send:false, and
// intake correctly parks the lead at needs_review. Loosening that rule would let unverified
// strangers into the pipeline. Instead a person who KNOWS a mailbox exists vouches for that ONE
// lead by address. It buys the lead the right to be DRAFTED — the Slack approval gate still
// stands between it and any send.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {}; const h = item.headers || {};
const got = q.t || q.token || h['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');

const b = item.body || {};
const action = String(b.action || 'seed').toLowerCase();
if (action !== 'seed' && action !== 'approve' && action !== 'cleanup') {
  throw new Error(`REFUSED: unknown action '${b.action}' — expected 'seed', 'approve' or 'cleanup'`);
}
if (action === 'cleanup') return { json: { action, tab: String(b.tab || 'Inbox') } };
const EMAIL = /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/;
if (action === 'approve') {
  const email = String(b.email || '').trim().toLowerCase();
  // Vouching for "whatever matches" is how the wrong person gets mailed. One exact address only.
  if (!EMAIL.test(email)) throw new Error('REFUSED: approve needs one valid email address');
  return { json: { action, email, force: b.force === true, reason: String(b.reason || 'human vouched: mailbox known to exist on a catch-all domain') } };
}
return { json: {
  action, status: '', notes: '', mapped_lead_id: '',
  Product: b.Product || 'OryonIQ',
  'First name': b.first_name || 'Wiring',
  'Last name': b.last_name || 'Test',
  'Company name': b.company || 'Wiring Test Co',
  'Email address': b.email || 'wiring-test@example.invalid',
  'Website': b.website || 'example.invalid',
} };

// Report what the tab ACTUALLY holds. The sheet audit derives its header list from the data
// rows, so an empty tab reports zero headers whether or not a header row exists — which is how a
// completely unprovisioned Inbox went unnoticed. Reading back a row we just wrote is the only
// honest proof that the header row is there and correctly named.
const WANT = ['status','notes','mapped_lead_id','Product','First name','Last name','Company name','Email address','Website'];
const rows = $input.all().map((i) => i.json || {});
const headers = [...new Set(rows.flatMap((r) => Object.keys(r)))].filter((k) => k !== 'row_number');
const missing = WANT.filter((h) => !headers.includes(h));
return [{ json: {
  ok: missing.length === 0 && rows.length > 0,
  rows_in_inbox: rows.length,
  headers_present: headers,
  headers_missing: missing,
  product_column_exists: headers.includes('Product'),
  newest_row: rows.length ? rows[rows.length - 1] : null,
  at: new Date().toISOString(),
} }];

// Find the ONE Leads row for this address and mark it approved.
//
// Refuses rather than guesses in every ambiguous case: no match, more than one match, or a row
// already past this point in the pipeline. Vouching is a statement about a specific person, so a
// fuzzy match here would put the wrong lead in front of a stranger.
const want = $('Authenticate (fail-closed)').first().json;
const email = String(want.email || '').toLowerCase();
const rows = $input.all().map((i) => i.json || {});
const hits = rows.filter((r) => String(r.contact_email || '').trim().toLowerCase() === email);

if (hits.length === 0) throw new Error(`REFUSED: no lead in Leads with address ${email}`);
if (hits.length > 1) throw new Error(`REFUSED: ${hits.length} rows share ${email} — refusing to guess which one`);

const row = hits[0];
const state = String(row.channel_state_email || '').trim().toLowerCase();
const verdict = String(row.verify_action || '').trim().toLowerCase();
const reoon = String(row.reoon_status || '').trim().toLowerCase();

// ⚠️ THE VERIFICATION VERDICT IS THE AUTHORITY, NOT THE LIFECYCLE COLUMN.
//
// This used to refuse on channel_state_email === 'dropped'. That reads like a safety check and is
// not one: channel_state_email is workflow BOOKKEEPING that several workflows write, and one of
// them was writing 'dropped' to mean "enrolment did not land" rather than "the address is not
// real". A lead with a perfectly good address was permanently locked out of the pipeline by a
// word another workflow chose (seen live 2026-08-30).
//
// What actually decides whether an address is a dead end is Reoon's own verdict, in verify_action
// / reoon_status, written once by VIO-intake-verify-curate and never overwritten. Refuse on that.
if (verdict === 'drop' || verdict === 'invalid' || reoon === 'invalid') {
  throw new Error(`REFUSED: ${email} was rejected by verification (verify_action='${verdict}', reoon_status='${reoon}') — a verified negative, not a judgement call`);
}
// Someone asking not to be contacted is also not a judgement call, and that IS a lifecycle fact.
if (state === 'unsubscribed' || state === 'bounced') {
  throw new Error(`REFUSED: ${email} is '${state}' — that is the prospect's decision, not ours`);
}
const VOUCHABLE = new Set(['needs_review', '']);
// `pending_approval` means a human was asked and has not answered — re-approving that would post
// a SECOND Slack request for the same lead. But a run that errors AFTER claiming the row (the
// enrolment gate refusing, say) strands it in that state forever, and nothing else can free it.
// So it is reachable only with an explicit force, which the caller has to mean.
if ((state === 'pending_approval' || state === 'dropped') && want.force !== true) {
  throw new Error(`REFUSED: ${email} is '${state}'. Pass force:true only to free a row stranded by a failed run — the address itself already passed the verification check above.`);
}
if (!VOUCHABLE.has(state) && state !== 'pending_approval' && state !== 'dropped') {
  throw new Error(`REFUSED: ${email} is '${state}' — it is already in the pipeline, nothing to vouch for`);
}
return [{ json: {
  row_number: row.row_number,
  channel_state_email: 'approved',
  verify_reason: String(want.reason || '').slice(0, 300),
  updated_at: new Date().toISOString(),
} }];

// Drop routing keys before they can become sheet columns.
//
// `action` tells THIS workflow which branch to take; it is not lead data. The append below runs
// with handlingExtraData:insertInNewColumn — which it must, because that is what bootstraps the
// header row on an empty tab — so any stray key on the item becomes a permanent column on a tab
// staff type into. It did: an `action` column appeared on Inbox, and the mapper then spent an
// OpenAI call on every row trying to work out what it meant.
const { action, force, reason, ...row } = $input.item.json;
return { json: row };

// Delete TEST rows, and make it structurally impossible to delete a real one.
//
// THE GUARD: a row is deletable only if its email address ends in a domain that CANNOT EXIST.
// `.invalid` is reserved by RFC 2606 precisely so it can never resolve, and `.test` likewise — no
// real prospect can ever have one. Every other row is left untouched, and this node refuses the
// whole batch if it is asked to touch anything else, rather than deleting "the safe ones" and
// leaving a half-done job nobody can reason about.
//
// A blank email is NOT deletable. That is a staff member mid-typing, and deleting their row while
// they fill it in is the worst thing this tool could do.
//
// Rows are returned HIGHEST FIRST. A sheet delete shifts every row below it up by one, so
// ascending order would make each delete land on the wrong row after the first.
const UNREACHABLE = /\.(invalid|test|example)$/i;
const tab = $('Authenticate (fail-closed)').first().json.tab || 'Inbox';
const rows = $input.all().map((i) => i.json || {});

const targets = [];
for (const r of rows) {
  const email = String(r.contact_email || r['Email address'] || '').trim().toLowerCase();
  if (!email) continue;                       // blank = someone is still typing
  const domain = email.split('@')[1] || '';
  if (!UNREACHABLE.test(domain)) continue;    // a real address: never touched
  if (r.row_number == null) continue;
  targets.push({ row_number: Number(r.row_number), email });
}
targets.sort((a, b) => b.row_number - a.row_number);

if (!targets.length) {
  return [{ json: { ok: true, tab, deleted: 0, note: 'no unreachable-domain rows found — nothing to clean' } }];
}
return targets.map((t) => ({ json: { tab, row_number: t.row_number, email: t.email } }));

const picked = $('Pick test rows').all().map((i) => i.json).filter((j) => j.row_number != null);
return [{ json: {
  ok: true,
  tab: picked.length ? picked[0].tab : 'n/a',
  deleted: picked.length,
  rows: picked.map((p) => `${p.row_number}: ${p.email}`),
  note: 'only rows whose email domain cannot exist (.invalid/.test/.example) were eligible',
} }];
